    VkAttachmentReference ar{0,VK_IMAGE_LAYOUT_COLOR_ATTACHMENT_OPTIMAL}; VkSubpassDescription sp{}; sp.pipelineBindPoint=VK_PIPELINE_BIND_POINT_GRAPHICS; sp.colorAttachmentCount=1; sp.pColorAttachments=&ar;
    VkRenderPassCreateInfo ri{VK_STRUCTURE_TYPE_RENDER_PASS_CREATE_INFO}; ri.attachmentCount=1; ri.pAttachments=&ad; ri.subpassCount=1; ri.pSubpasses=&sp; VkRenderPass rp{}; VK_CHECK(vkCreateRenderPass(dev,&ri,nullptr,&rp));
    VkFramebufferCreateInfo fi{VK_STRUCTURE_TYPE_FRAMEBUFFER_CREATE_INFO}; fi.renderPass=rp; fi.attachmentCount=1; fi.pAttachments=&view; fi.width=W; fi.height=H; fi.layers=1; VkFramebuffer fb{}; VK_CHECK(vkCreateFramebuffer(dev,&fi,nullptr,&fb));
