    VkPipelineMultisampleStateCreateInfo ms{VK_STRUCTURE_TYPE_PIPELINE_MULTISAMPLE_STATE_CREATE_INFO}; ms.rasterizationSamples=VK_SAMPLE_COUNT_1_BIT; VkPipelineColorBlendAttachmentState ba{}; ba.colorWriteMask=15; VkPipelineColorBlendStateCreateInfo bs{VK_STRUCTURE_TYPE_PIPELINE_COLOR_BLEND_STATE_CREATE_INFO}; bs.attachmentCount=1; bs.pAttachments=&ba;
    VkGraphicsPipelineCreateInfo gpi{VK_STRUCTURE_TYPE_GRAPHICS_PIPELINE_CREATE_INFO}; gpi.stageCount=2; gpi.pStages=stages; gpi.pVertexInputState=&vin; gpi.pInputAssemblyState=&ia; gpi.pViewportState=&vps; gpi.pRasterizationState=&rs; gpi.pMultisampleState=&ms; gpi.pColorBlendState=&bs; gpi.layout=pl; gpi.renderPass=rp; VkPipeline pipe{}; VK_CHECK(vkCreateGraphicsPipelines(dev,VK_NULL_HANDLE,1,&gpi,nullptr,&pipe));
