    const uint8_t clear[3][4]={{17,43,91,255},{29,71,113,255},{47,101,149,255}}; const uint8_t draw[3][4]={{211,31,67,255},{173,89,23,255},{137,53,227,255}};
    for(uint32_t frame=0;frame<3;frame++) {
        uint32_t i=epoch*3+frame; uint8_t c[4],d[4]; for(int k=0;k<4;k++){c[k]=uint8_t(clear[frame][k]+epoch*(k<3?11:0)); d[k]=uint8_t(draw[frame][k]-epoch*(k<3?7:0));}
        VkCommandBufferBeginInfo cbbi{VK_STRUCTURE_TYPE_COMMAND_BUFFER_BEGIN_INFO}; VK_CHECK(vkBeginCommandBuffer(cb,&cbbi)); VkClearValue cv{}; for(int k=0;k<4;k++) cv.color.float32[k]=c[k]/255.0f; VkRenderPassBeginInfo rbi{VK_STRUCTURE_TYPE_RENDER_PASS_BEGIN_INFO}; rbi.renderPass=rp; rbi.framebuffer=fb; rbi.renderArea.extent={W,H}; rbi.clearValueCount=1; rbi.pClearValues=&cv; vkCmdBeginRenderPass(cb,&rbi,VK_SUBPASS_CONTENTS_INLINE); vkCmdBindPipeline(cb,VK_PIPELINE_BIND_POINT_GRAPHICS,pipe); float color[4]; for(int k=0;k<4;k++)color[k]=d[k]/255.0f; vkCmdPushConstants(cb,pl,VK_SHADER_STAGE_FRAGMENT_BIT,0,16,color); vkCmdDraw(cb,3,1,0,0); vkCmdEndRenderPass(cb);
        VkImageMemoryBarrier bar{VK_STRUCTURE_TYPE_IMAGE_MEMORY_BARRIER}; bar.srcAccessMask=VK_ACCESS_COLOR_ATTACHMENT_WRITE_BIT; bar.dstAccessMask=VK_ACCESS_TRANSFER_READ_BIT; bar.oldLayout=bar.newLayout=VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL; bar.srcQueueFamilyIndex=bar.dstQueueFamilyIndex=VK_QUEUE_FAMILY_IGNORED; bar.image=image; bar.subresourceRange={VK_IMAGE_ASPECT_COLOR_BIT,0,1,0,1}; vkCmdPipelineBarrier(cb,VK_PIPELINE_STAGE_COLOR_ATTACHMENT_OUTPUT_BIT,VK_PIPELINE_STAGE_TRANSFER_BIT,0,0,nullptr,0,nullptr,1,&bar); VkBufferImageCopy copy{}; copy.imageSubresource={VK_IMAGE_ASPECT_COLOR_BIT,0,0,1}; copy.imageExtent={W,H,1}; vkCmdCopyImageToBuffer(cb,image,VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL,buf,1,&copy); VK_CHECK(vkEndCommandBuffer(cb));
        VkSubmitInfo si{VK_STRUCTURE_TYPE_SUBMIT_INFO}; si.commandBufferCount=1; si.pCommandBuffers=&cb; VK_CHECK(vkQueueSubmit(queue,1,&si,fence)); VK_CHECK(vkWaitForFences(dev,1,&fence,VK_TRUE,5000000000ull)); void* mapped{}; VK_CHECK(vkMapMemory(dev,bmem,0,size,0,&mapped)); auto* p=static_cast<uint8_t*>(mapped); auto exact=[&](uint32_t x,uint32_t y,const uint8_t* want){return std::memcmp(p+4*(y*W+x),want,4)==0;}; if(!exact(2,2,c)||!exact(32,32,d)){std::fprintf(stderr,"FAIL: epoch=%u frame=%u pixel mismatch\n",epoch,frame); std::exit(1);} checksum=fnv(checksum,p,size); vkUnmapMemory(dev,bmem); VK_CHECK(vkResetFences(dev,1,&fence)); VK_CHECK(vkResetCommandBuffer(cb,0)); (void)i;
    }
